// 节流函数：在指定时间间隔内最多执行一次
function throttle<T extends Function>(func: T, delay: number): T {
  let lastCall = 0;
  let timeoutId: NodeJS.Timeout | null = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return function (this: unknown, ...args: any[]) {
    const now = Date.now();
    const remaining = delay - (now - lastCall);
    if (remaining <= 0) {
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
      lastCall = now;
      return (func as Function).apply(this, args);
    } else if (!timeoutId) {
      timeoutId = setTimeout(() => {
        lastCall = Date.now();
        timeoutId = null;
        (func as Function).apply(this, args);
      }, remaining);
    }
  } as unknown as T;
}
// 防抖函数：在指定时间间隔内多次调用只执行最后一次
function debounce<T extends Function>(func: T, delay: number): T {
  let timeoutId: NodeJS.Timeout | null = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return function (this: unknown, ...args: any[]) {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      timeoutId = null;
      (func as Function).apply(this, args);
    }, delay);
  } as unknown as T;
}
